#nullable enable

using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using Nafadh_Backend.Models;
using Nafadh_Backend.Interfaces;
using Nafadh_Backend.DTOs;
using System.Linq;

namespace Nafadh_Backend.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    public class DepartmentController : ControllerBase
    {
        private readonly IDepartmentRepository _deptRepo;

        public DepartmentController(IDepartmentRepository deptRepo)
        {
            _deptRepo = deptRepo;
        }


        //get _Departments within a company
        [HttpGet("company/{companyId}")]
        public async Task<IActionResult> GetDepartmentsByCompany(int companyId)
        {
            var departments = await _deptRepo.GetByCompanyIdAsync(companyId);
            var dtos = departments.Select(d => new DepartmentDto
            {
                DepartmentId = d.DepartmentId,
                Name = d.Name,
                CompanyId = d.CompanyId
            });
            return Ok(dtos);
        }
        //

        //post _Create a department/project team
        [HttpPost]
        public async Task<IActionResult> CreateDepartment([FromBody] CreateDepartmentDto createDto)
        {
            var department = new NFD_Department
            {
                Name = createDto.Name,
                CompanyId = createDto.CompanyId
            };

            await _deptRepo.AddAsync(department);
            return CreatedAtAction(nameof(GetDepartmentsByCompany), new { companyId = department.CompanyId }, department);
        }

        //put _ Rename/update a department
        [HttpPut("{id}")]
        public async Task<IActionResult> UpdateDepartment(int id, [FromBody] UpdateDepartmentDto updateDto)
        {
            var department = await _deptRepo.GetByIdAsync(id);
            if (department == null) return NotFound();

            department.Name = updateDto.Name;

            await _deptRepo.UpdateAsync(department);
            return NoContent();
        }


        //delete _ Remove a department
        [HttpDelete("{id}")]
        public async Task<IActionResult> RemoveDepartment(int id)
        {
            var department = await _deptRepo.GetByIdAsync(id);
            if (department == null) return NotFound();

            await _deptRepo.DeleteAsync(department);
            return NoContent();
        }

        //get _ Compare enrollment outcomes across a department
        [HttpGet("{id}/performance")]
        public async Task<IActionResult> GetDepartmentPerformance(int id)
        {
            var performanceData = await _deptRepo.GetDepartmentPerformanceAsync(id);
            return Ok(performanceData);
        }
    }
}